import numpy as np
from copy import deepcopy

def solve_demo3(grid):
    """
    Grid transformation rule for task-8625f9bc:
    1. For rows with 2+ zeros: fill 5s between consecutive zeros
    2. For the top row (first row in input with 2+ zeros), extend LEFT from the first zero
    3. For BB edge columns (min/max columns in bounding box of all zeros) that have zeros:
       - Fill BETWEEN adjacent zero rows
       - PLUS: for left-most BB edge column, ALSO fill from min_row+1 to first_zero_row-1
    """
    result = deepcopy(grid)
    rows, cols = grid.shape

    # Find all zero positions
    zero_positions = [(r,c) for r in range(rows) for c in range(cols) if grid[r,c] == 0]
    if not zero_positions:
        return result

    # Bounding box of all zeros
    min_r, max_r = min(r for r,c in zero_positions), max(r for r,c in zero_positions)
    all_zero_cols = set(c for r,c in zero_positions)
    min_c, max_c = min(all_zero_cols), max(all_zero_cols)

    # Find rows with 2+ zeros
    rows_2plus = {}
    for r in range(rows):
        zeros = [c for c in range(cols) if grid[r][c] == 0]
        if len(zeros) >= 2:
            rows_2plus[r] = zeros

    # Step 1: Row fills (include left extend from top row)
    for r in sorted(rows_2plus.keys()):
        zeros = rows_2plus[r]
        # Extend left from first zero for top row only
        if r == min(rows_2plus.keys()):
            for c in range(zeros[0]):
                if result[r][c] == 5:
                    result[r][c] = 2
        # Fill between consecutive zeros
        for i in range(len(zeros) - 1):
            for c in range(zeros[i] + 1, zeros[i+1]):
                if result[r][c] == 5:
                    result[r][c] = 2

    # Step 2: Vertical fills at BB edge columns
    edge_cols = [min_c, max_c]  # Both left and right BB edge columns
    for c in edge_cols:
        # Zeros in this column
        zero_rows = sorted([r for r in range(rows) if grid[r][c] == 0])
        for i in range(len(zero_rows) - 1):
            r1, r2 = zero_rows[i], zero_rows[i+1]
            for r in range(r1 + 1, r2):
                if result[r][c] == 5:
                    result[r][c] = 2
        # PLUS upward extend from top row for LEFT BB edge column only
        if c == min_c and zero_rows and len(zero_rows) > 0:
            for r in range(min_r + 1, zero_rows[0]):
                if result[r][c] == 5:
                    result[r][c] = 2

    return result

